<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { useRouter } from 'vue-router';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import PasswordInput from '@/components/PasswordInput.vue';
import ProfilePhotoEditor from '@/components/ProfilePhotoEditor.vue';
import { useMediaSettings } from '@/composables/useMediaSettings';
import { api, errorMessage } from '@/api/client';
import { useAuth } from '@/stores/auth';
import type { AccountSettings, ApiResponse } from '@/types/api';
const { media, checking, mediaError, refreshMedia } = useMediaSettings();
const account = ref<AccountSettings | null>(null), loading = ref(true), busy = ref(false), error = ref(''), notice = ref('');
const profile = reactive({ fullName: '', phone: '', location: '' });
const email = reactive({ newEmail: '', currentPassword: '' }), passwords = reactive({ currentPassword: '', newPassword: '', confirmation: '' });
const { refresh } = useAuth(), router = useRouter();
async function load(preserveProfile = false) { try { account.value = (await api.get<ApiResponse<AccountSettings>>('/account/me')).data.data; if (!preserveProfile) Object.assign(profile, { fullName: account.value.profile?.fullName ?? '', phone: account.value.profile?.phone ?? '', location: account.value.profile?.location ?? '' }); } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } }
async function submit(kind: 'profile' | 'email' | 'password') {
  busy.value = true; error.value = ''; notice.value = '';
  try {
    if (kind === 'profile') { await api.patch('/account/profile', { ...profile, phone: profile.phone || null, location: profile.location || null }); notice.value = 'Personal profile saved.'; await load(); await refresh(); }
    if (kind === 'email') { await api.post('/account/email-change', email); email.currentPassword = ''; notice.value = 'Check your new email for a verification link. Your current address remains active until verification.'; }
    if (kind === 'password') { await api.post('/account/password-change', passwords); Object.assign(passwords, { currentPassword: '', newPassword: '', confirmation: '' }); await refresh(); await router.push({ path: '/login', query: { changed: 'password' } }); }
  } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; }
}
async function imageSaved() { notice.value = 'Profile picture saved.'; await load(true); await refresh(); }
onMounted(() => { void load(); });
</script>
<template><DashboardLayout><section class="mx-auto max-w-3xl space-y-6 p-5 lg:p-10"><h1 class="text-h1">Account Settings</h1><ApiAlert :message="error"/><ApiAlert :message="notice" kind="success"/><p v-if="loading" role="status">Loading your account…</p><button v-if="!account && !loading" class="secondary-button" @click="load()">Retry</button><template v-if="account"><form class="space-y-5 border bg-white p-6" @submit.prevent="submit('profile')"><h2 class="text-h2">Personal profile</h2><label for="account-name" class="field-label">Full name</label><input id="account-name" v-model.trim="profile.fullName" class="field-input" required minlength="2" maxlength="150" autocomplete="name"><label for="account-phone" class="field-label">Phone number</label><input id="account-phone" v-model.trim="profile.phone" type="tel" maxlength="30" class="field-input" autocomplete="tel"><label for="account-location" class="field-label">Location</label><input id="account-location" v-model.trim="profile.location" maxlength="500" class="field-input"><button class="primary-button" :disabled="busy">Save personal profile</button><RouterLink v-if="account.role === 'ALUMNI'" to="/profile" class="ml-4 inline-block underline">Edit alumni details</RouterLink></form><ProfilePhotoEditor :image="account.profile?.profileImage ?? null" :version="account.profile?.imageVersion ?? 0" :enabled="media.enabled" :checking="checking" :availability-error="mediaError" :unavailable-reason="media.unavailableReason" @refresh="refreshMedia" :can-configure="account.role === 'SUPER_ADMIN'" :max-bytes="media.maxBytes" :ready="Boolean(account.profile)" @saved="imageSaved"/><form class="space-y-5 border bg-white p-6" @submit.prevent="submit('email')"><h2 class="text-h2">Change email</h2><label for="current-email" class="field-label">Current email</label><input id="current-email" :value="account.email" readonly class="field-input"><p v-if="!account.emailChangeAvailable" role="status">Email changes are temporarily unavailable because email verification is not enabled. Please contact the platform administrator for assistance.</p><label for="new-email" class="field-label">New email</label><input id="new-email" v-model.trim="email.newEmail" type="email" required maxlength="254" class="field-input" autocomplete="email" :disabled="!account.emailChangeAvailable"><label for="email-password" class="field-label">Current password to change email</label><PasswordInput id="email-password" v-model="email.currentPassword" required autocomplete="current-password" :disabled="!account.emailChangeAvailable"/><button class="primary-button" :disabled="busy || !account.emailChangeAvailable">Request email change</button></form><form class="space-y-5 border bg-white p-6" @submit.prevent="submit('password')"><h2 class="text-h2">Change password</h2><p>Use at least eight characters with letters and a number or symbol. Updating your password signs out every session, including this one.</p><label for="current-password" class="field-label">Current password</label><PasswordInput id="current-password" v-model="passwords.currentPassword" required autocomplete="current-password"/><label for="new-password" class="field-label">New password</label><PasswordInput id="new-password" v-model="passwords.newPassword" required minlength="8" maxlength="72" autocomplete="new-password"/><label for="confirm-new-password" class="field-label">Confirm new password</label><PasswordInput id="confirm-new-password" v-model="passwords.confirmation" required maxlength="72" autocomplete="new-password"/><button class="primary-button" :disabled="busy">Update password</button></form></template></section></DashboardLayout></template>
